components.css:
.ds-switch { position: relative; width: 3rem; height: 1.75rem; flex-shrink: 0; cursor: pointer; appearance: none; border-radius: 999px; border: 1px solid var(--color-line-strong); background: var(--color-surface); transition: background-color .2s, border-color .2s; }
.ds-switch::before { content: ""; position: absolute; top: .125rem; left: .125rem; width: 1.25rem; height: 1.25rem; border-radius: 999px; background: var(--color-ink-faint); transition: transform .2s, background-color .2s; }
.ds-switch:checked { background: var(--color-ink); border-color: var(--color-ink); }
.ds-switch:checked::before { transform: translateX(1.25rem); background: var(--color-ground); }
.ds-switch:focus-visible { outline: 2px solid var(--color-accent); outline-offset: 3px; }

.ds-filter-chip { display: inline-flex; align-items: center; gap: .5rem; min-height: 2.75rem; padding: 0 1rem; border-radius: 999px; border: 1px solid var(--color-line); background: transparent; color: var(--color-ink-dim); font: 700 .875rem/1 inherit; white-space: nowrap; cursor: pointer; transition: color .2s, border-color .2s, background-color .2s; }
.ds-filter-chip:hover { border-color: var(--color-line-strong); color: var(--color-ink); }
.ds-filter-chip[aria-pressed="true"] { background: var(--color-ink); color: var(--color-ground); border-color: transparent; }
.ds-filter-chip:focus-visible { outline: 2px solid var(--color-accent); outline-offset: 3px; }
.ds-filter-count { font-size: .75rem; font-variant-numeric: tabular-nums; color: var(--color-ink-faint); }
.ds-filter-chip[aria-pressed="true"] .ds-filter-count { color: var(--color-ground); opacity: .7; }

.ds-field { min-height: 2.75rem; padding: 0 1rem; border-radius: 999px; border: 1px solid var(--color-line); background: var(--color-surface); color: var(--color-ink); font: 400 1rem/1 inherit; font-variant-numeric: tabular-nums; transition: border-color .2s; }
.ds-field:hover { border-color: var(--color-line-strong); }
.ds-field:focus-visible { outline: 2px solid var(--color-accent); outline-offset: 3px; }
.ds-select { appearance: none; padding-right: 2.75rem; background-image: url("data:image/svg+xml;utf8,<svg xmlns='http://www.w3.org/2000/svg' viewBox='0 0 24 24' fill='none' stroke='%23869dae' stroke-width='2' stroke-linecap='round' stroke-linejoin='round'><path d='m6 9 6 6 6-6'/></svg>"); background-repeat: no-repeat; background-position: right .9rem center; background-size: 18px; }

.ds-marks { display: flex; flex-wrap: wrap; align-items: center; justify-content: center; gap: .5rem; margin: 0; padding: 0; list-style: none; }
.ds-mark { display: grid; place-content: center; width: 2.25rem; height: 2.25rem; border-radius: 999px; border: 1px solid var(--color-line); color: var(--color-ink-faint); font: 800 .75rem/1 inherit; font-variant-numeric: tabular-nums; }
.ds-mark-done { background: var(--color-ink); border-color: var(--color-ink); color: var(--color-ground); }
.ds-mark-now { border-color: var(--color-accent); color: var(--color-accent); }

.ds-bento { display: flex; flex-direction: column; border-radius: 14px; border: 1px solid var(--color-line); padding: 1.25rem; background-image: linear-gradient(to bottom, color-mix(in oklab, var(--color-raised) 85%, var(--color-accent) 4%), var(--color-surface) 62%); }
.ds-bento-title { margin: 0; font: 800 1rem/1.3 inherit; color: var(--color-ink); }
.ds-bento-body { margin: .5rem 0 0; font: 400 .875rem/1.5 inherit; color: var(--color-ink-dim); }
.ds-bento-figure { display: block; margin-top: 1.5rem; font: 800 1.875rem/1 inherit; font-variant-numeric: tabular-nums; color: var(--color-ink); }

.ds-mcell { display: flex; flex-direction: column; align-items: center; gap: .375rem; }
.ds-mcell-n { font: 700 .875rem/1 inherit; font-variant-numeric: tabular-nums; color: var(--color-ink); }
.ds-mcell-track { display: block; width: 100%; height: .375rem; overflow: hidden; border-radius: 999px; background: var(--color-line); }
.ds-mcell-fill { display: block; height: 100%; border-radius: 999px; background: var(--color-ink-dim); }

.ds-scell { display: flex; min-height: 4rem; flex-direction: column; justify-content: center; gap: .125rem; border-radius: 14px; border: 1px dashed var(--color-line); padding: .5rem .75rem; text-decoration: none; transition: border-color .2s; }
.ds-scell-done { border-style: solid; border-color: color-mix(in oklab, var(--color-ink) 70%, transparent); background: var(--color-surface); }
.ds-scell:hover { border-color: var(--color-line-strong); }
.ds-scell-t { font: 700 .75rem/1.3 inherit; color: var(--color-ink-dim); }
.ds-scell-m { font: 400 .75rem/1.3 inherit; font-variant-numeric: tabular-nums; color: var(--color-ink); }
.ds-scell-p { color: var(--color-ink-faint); }
